def proper_divisor_sum(n):
    # Validate that n is a positive built-in int
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be a positive built-in int")

    # Check if n is positive
    if n <= 0:
        raise ValueError("Input must be a positive integer")

    # Special case: if n is 1, return 0
    if n == 1:
        return 0

    # Calculate sum of all proper divisors (strictly smaller than n)
    divisor_sum = 0
    for i in range(1, n):
        if n % i == 0:
            divisor_sum += i

    return divisor_sum

