import re

def ascii_word_counts(text):
    # Find all maximal runs of ASCII letters
    words = re.findall(r'[a-zA-Z]+', text)
    # Convert to lowercase and count
    word_counts = {}
    for word in words:
        word_lower = word.lower()
        word_counts[word_lower] = word_counts.get(word_lower, 0) + 1
    return word_counts

