def compose_permutations(left, right):
    # Validate inputs
    if not isinstance(left, list) or not isinstance(right, list):
        raise ValueError("Both inputs must be lists")

    if len(left) != len(right):
        raise ValueError("Both lists must have the same length")

    if len(left) == 0:
        return []

    # Validate that both lists contain valid permutations
    n = len(left)
    expected_set = set(range(n))

    if set(left) != expected_set:
        raise ValueError("Left list must contain every integer from 0 to n-1 exactly once")

    if set(right) != expected_set:
        raise ValueError("Right list must contain every integer from 0 to n-1 exactly once")

    # Compose the permutations
    result = [left[right[i]] for i in range(n)]
    return result

