def matrix_product(a, b):
    # Validate matrix a
    if not a or not a[0]:
        raise ValueError("Matrix a must have at least one row and one column")

    rows_a = len(a)
    cols_a = len(a[0])

    # Check that all rows in a have equal length
    for row in a:
        if len(row) != cols_a:
            raise ValueError("All rows in matrix a must have equal length")

    # Validate matrix b
    if not b or not b[0]:
        raise ValueError("Matrix b must have at least one row and one column")

    rows_b = len(b)
    cols_b = len(b[0])

    # Check that all rows in b have equal length
    for row in b:
        if len(row) != cols_b:
            raise ValueError("All rows in matrix b must have equal length")

    # Check that columns of a equal rows of b
    if cols_a != rows_b:
        raise ValueError("Columns of matrix a must equal rows of matrix b")

    # Compute matrix product
    result = []
    for i in range(rows_a):
        row = []
        for j in range(cols_b):
            sum_product = 0
            for k in range(cols_a):
                sum_product += a[i][k] * b[k][j]
            row.append(sum_product)
        result.append(row)

    return result

