def parse_rgb(text):
    # Check if input is a string
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    # Check if string has exactly 7 characters
    if len(text) != 7:
        raise ValueError("String must be exactly 7 characters long")

    # Check if first character is '#'
    if text[0] != '#':
        raise ValueError("String must start with '#'")

    # Check if remaining 6 characters are valid hex digits
    hex_chars = text[1:]
    for char in hex_chars:
        if char not in '0123456789ABCDEFabcdef':
            raise ValueError("Invalid hexadecimal digit")

    # Parse the RGB values
    red = int(hex_chars[0:2], 16)
    green = int(hex_chars[2:4], 16)
    blue = int(hex_chars[4:6], 16)

    return (red, green, blue)

