def parse_signed_decimal(text):
    # Check if input is a string
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    # Check for empty string
    if not text:
        raise ValueError("Empty input")

    # Check for whitespace
    if any(c.isspace() for c in text):
        raise ValueError("Whitespace not allowed")

    # Check for underscores
    if '_' in text:
        raise ValueError("Underscores not allowed")

    # Check for decimal points
    if '.' in text:
        raise ValueError("Decimal points not allowed")

    # Check for valid characters and signs
    if text[0] == '+' or text[0] == '-':
        # If there's a sign, check that the rest are digits
        if len(text) == 1:
            raise ValueError("Sign alone not allowed")
        if not text[1:].isdigit():
            raise ValueError("Invalid characters")
    else:
        # No sign, check that all are digits
        if not text.isdigit():
            raise ValueError("Invalid characters")

    # Check for multiple signs (shouldn't happen with the above logic, but just in case)
    plus_count = text.count('+')
    minus_count = text.count('-')
    if plus_count + minus_count > 1:
        raise ValueError("Multiple signs not allowed")

    # Parse the integer
    try:
        result = int(text)
        return result
    except ValueError:
        raise ValueError("Invalid integer format")

